import { CommonModule } from '@angular/common';
import { HttpContext } from '@angular/common/http';
import {
  ChangeDetectorRef,
  Component,
  DestroyRef,
  effect,
  inject,
  OnInit,
  signal,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import {
  AbstractControl,
  FormGroup,
  ReactiveFormsModule,
  ValidationErrors,
  Validators,
} from '@angular/forms';
import { ButtonModule } from 'primeng/button';
import { DynamicDialogRef, DynamicDialogConfig } from 'primeng/dynamicdialog';

import {
  EntitiesService,
  AssetMoveRequest,
  AssetMoveResponse,
  AssetMoveSummary,
  ClientListItem,
  AccountsService,
} from '../../../../../api';
import {
  hasProperty,
  isDefined,
  isNullOrUndefined,
} from '../../../../../shared/utils';
import { BroadcastEventMessageService } from '../../../services/broadcast-event-messages.service';
import { BulkSelectionService } from '../../../services/bulk-selection.service';
import {
  createAutocompleteField,
  createDropdownField,
  FormAction,
  FormFieldConfig,
} from '../../../../../shared/models';
import { DynamicFormComponent } from '../../../../../shared/components/forms/dynamic-form/dynamic-form.component';
import {
  Observable,
  Subject,
  debounceTime,
  switchMap,
  of,
  catchError,
  from,
  concatMap,
  defer,
  EMPTY,
  finalize,
  map,
} from 'rxjs';
import { UtilityService } from '../../../../../core/services/utility.service';
import { SEARCH_DEBOUNCE_TIME } from '../../../../../core/models';
import { ApiErrorResponse } from '../../../../../core/models/auth.model';
import { SILENT_ERROR } from '../../../../../core/models/http-context.constants';
import { TranslatePipe, TranslateService } from '@ngx-translate/core';

/** Where one asset of a move stands: before, while and after it is sent. */
export type AssetMoveStatus =
  | 'waiting'
  | 'moving'
  | 'moved'
  | 'restored'
  | 'blocked'
  | 'failed'
  | 'skipped';

/** One asset's line in the move dialog's result list. */
export interface AssetMoveResult {
  id: string;
  name: string;
  status: AssetMoveStatus;
  message?: string;
}

/** Valid only once a client is picked from the suggestions: typed text alone has no id to move to. */
function requireSelectedClient(
  control: AbstractControl,
): ValidationErrors | null {
  const value = control.value as { id?: string } | null | undefined;
  return isDefined(value?.id) ? null : { required: true };
}

@Component({
  selector: 'app-asset-move-form',
  imports: [
    CommonModule,
    ReactiveFormsModule,
    ButtonModule,
    DynamicFormComponent,
    TranslatePipe,
  ],
  templateUrl: './asset-move-form.component.html',
  styleUrl: './asset-move-form.component.scss',
})
export class AssetMoveFormComponent implements OnInit {
  private readonly entitiesService = inject(EntitiesService);
  private readonly broadcastService = inject(BroadcastEventMessageService);
  private readonly utilityService = inject(UtilityService);
  private readonly accountsService = inject(AccountsService);
  protected readonly destroyRef = inject(DestroyRef);
  private readonly dialogRef = inject(DynamicDialogRef);
  private readonly dialogConfig = inject(DynamicDialogConfig);
  private readonly bulkSelectionService = inject(BulkSelectionService);
  protected readonly translate = inject(TranslateService);

  ownerId: string | null = null;
  /** The client the assets are moved out of; it is not offered as a destination. */
  sourceClientId: string | null = null;
  /** Assets still to move. Each one is removed as soon as it has moved, so it is never sent twice. */
  assetIds: string[] = [];
  /** Display names by asset id, for the result list. */
  private names = new Map<string, string>();
  /** One line per asset of the last batch: moved, restored into a deleted copy, blocked or failed, with the reason. */
  protected readonly results = signal<AssetMoveResult[]>([]);
  /** The batch is over: the form gives way to the result list and a Close button. */
  protected readonly finished = signal(false);
  /** True while a batch is being sent, so a second OK click cannot start a parallel batch. */
  protected readonly moving = signal(false);
  private cancelRequested = false;
  protected formFields: FormFieldConfig[] = [];
  clientsSearchResults = signal<ClientListItem[] | undefined>(undefined);
  private readonly searchSubject = new Subject<string>();
  private readonly cdr = inject(ChangeDetectorRef);
  protected actions: FormAction[] = this.buildDefaultActions();

  constructor() {
    effect(() => {
      const searchResults = this.clientsSearchResults();
      const field = this.formFields.find(
        (f) => f.key === 'destinationClientId',
      );
      if (field?.props) {
        // Update the suggestions
        field.props = {
          ...field.props,
          suggestions: searchResults,
        };
      }
      this.cdr.detectChanges();
    });
  }

  ngOnInit(): void {
    if (isDefined(this.dialogConfig.data)) {
      this.ownerId = this.dialogConfig.data.ownerId ?? null;
      this.sourceClientId = this.dialogConfig.data.sourceClientId ?? null;

      this.assetIds = this.dialogConfig.data.assetIds ?? [];
      const assets = (this.dialogConfig.data.assets ?? []) as {
        id: string;
        name: string;
      }[];
      this.names = new Map(assets.map((asset) => [asset.id, asset.name]));
    }
    this.formFields = [
      createAutocompleteField(
        'destinationClientId',
        this.translate.instant('ADMIN.ASSETS.MOVE.FIELDS.DESTINATION_CLIENT'),
        [],
        this.clientsSearchResults(),
        this.searchClient.bind(this),
        {
          layout: 'horizontal',
          labelWidth: '1/3',
          name: 'destinationClientId',
          props: {
            appendTo: 'body',
            showClear: true,
            multiple: false,
            field: 'name',
            completeOnFocus: false,
            typeahead: true,
            showEmptyMessage: true,
            emptyMessage: this.translate.instant(
              'SHARED.CLIENT_SELECTION_FORM',
              {
                count: 0,
              },
            ),
          },
          validations: [
            {
              name: 'required',
              validator: requireSelectedClient,
              message: this.translate.instant(
                'SHARED.COMMON.FORMS.SHARED.REQUIRED',
                {
                  field: this.translate.instant(
                    'ADMIN.ASSETS.MOVE.FIELDS.DESTINATION_CLIENT',
                  ),
                },
              ),
            },
          ],
        },
      ),
      createDropdownField(
        'includeDevice',
        this.translate.instant('ADMIN.ASSETS.MOVE.FIELDS.INCLUDE_DEVICE'),
        [
          {
            label: this.translate.instant('SHARED.COMMON.FORMS.CHECKBOX.YES'),
            value: true,
          },
          {
            label: this.translate.instant('SHARED.COMMON.FORMS.CHECKBOX.NO'),
            value: false,
          },
        ],
        true,
        {
          layout: 'horizontal',
          labelWidth: '1/3',
          name: 'includeDevice',
          props: {
            appendTo: 'body',
          },
          validations: [
            {
              name: 'required',
              validator: Validators.required,
              message: this.translate.instant(
                'SHARED.COMMON.FORMS.SHARED.REQUIRED',
                {
                  field: this.translate.instant(
                    'ADMIN.ASSETS.MOVE.FIELDS.INCLUDE_DEVICE',
                  ),
                },
              ),
            },
          ],
        },
      ),
      createDropdownField(
        'includeSimCard',
        this.translate.instant('ADMIN.ASSETS.MOVE.FIELDS.INCLUDE_SIMCARD'),
        [
          {
            label: this.translate.instant('SHARED.COMMON.FORMS.CHECKBOX.YES'),
            value: true,
          },
          {
            label: this.translate.instant('SHARED.COMMON.FORMS.CHECKBOX.NO'),
            value: false,
          },
        ],
        true,
        {
          layout: 'horizontal',
          labelWidth: '1/3',
          name: 'includeSimCard',
          props: {
            appendTo: 'body',
          },
        },
      ),
    ];
    this.setUpClientsSearch();
  }

  protected buildDefaultActions(): FormAction[] {
    return [
      {
        label: this.translate.instant('SHARED.COMMON.BUTTONS.CANCEL'),
        action: () => this.onCancel(),
        severity: 'secondary',
      },
      {
        label: this.translate.instant('SHARED.COMMON.BUTTONS.OK'),
        action: (formData: FormGroup) => {
          const value = {
            ...formData.value,
            destinationClientId: formData.value['destinationClientId']?.id,
          };
          this.onWizardComplete(value as AssetMoveRequest);
        },
        severity: 'primary',
        disabled: (form?: FormGroup) => {
          if (isNullOrUndefined(form) || this.moving()) return true;
          return form.pristine || form.invalid;
        },
        loading: () => this.moving(),
      },
    ];
  }

  private setUpClientsSearch(): void {
    this.searchSubject
      .pipe(
        debounceTime(SEARCH_DEBOUNCE_TIME),
        takeUntilDestroyed(this.destroyRef),
        switchMap((searchTerm) => {
          const trimmedSearchTerm = searchTerm.trim();

          if (trimmedSearchTerm.length === 0) {
            return of({ items: [] });
          }

          const filters = {
            state: { value: 'active', operator: '=' },
            name: { value: `*${trimmedSearchTerm}*`, operator: '=' },
          };
          const rqlFilter = this.utilityService.constructRqlFilter(filters);

          return this.accountsService
            .listClients(this.ownerId ?? '', 0, 10, 'name', rqlFilter)
            .pipe(
              catchError(() => {
                return of({ items: [] });
              }),
            );
        }),
      )
      .subscribe({
        next: (data) => {
          if (isDefined(data) && hasProperty(data, 'items')) {
            const clients = isNullOrUndefined(data.items) ? [] : data.items;
            this.clientsSearchResults.set(
              clients.filter((client) => client.id !== this.sourceClientId),
            );
          }
        },
        error: () => {
          this.clientsSearchResults.set([]);
        },
      });
  }

  searchClient(searchTerm: string) {
    this.clientsSearchResults.set(undefined);
    this.searchSubject.next(searchTerm);
  }

  onWizardComplete(context: AssetMoveRequest): void {
    if (
      this.moving() ||
      this.assetIds.length === 0 ||
      isNullOrUndefined(context.destinationClientId) ||
      // The source client is filtered out of the suggestions; this only guards a stale selection.
      String(context.destinationClientId) === String(this.sourceClientId)
    ) {
      return;
    }

    this.moving.set(true);
    this.cancelRequested = false;
    const batch = [...this.assetIds];
    const movedIds: string[] = [];
    this.results.set(
      batch.map((id) => ({ id, name: this.nameOf(id), status: 'waiting' })),
    );

    from(batch)
      .pipe(
        // Checked as each asset's turn comes, so Cancel stops after the move already in flight. A failed move does
        // not stop the batch: its reason goes in the result list.
        concatMap((id) =>
          this.cancelRequested ? EMPTY : this.moveOne(id, context),
        ),
        takeUntilDestroyed(this.destroyRef),
        // However the batch ends (done, failed, or the dialog closed mid-way), the assets that moved leave the
        // bulk selection and the dialog stops counting as busy.
        finalize(() => {
          this.moving.set(false);
          this.dropFromBulkSelection(movedIds);
        }),
      )
      .subscribe({
        next: (result) => {
          this.setResult(result);
          if (result.status === 'moved' || result.status === 'restored') {
            movedIds.push(result.id);
            this.assetIds = this.assetIds.filter(
              (assetId) => assetId !== result.id,
            );
          }
        },
        complete: () => this.finishBatch(),
        // moveOne turns every failed request into a result, so this only catches an unexpected error.
        error: () =>
          this.finishBatch(
            this.translate.instant('ADMIN.ASSETS.MOVE.RESULT.UNKNOWN_ERROR'),
          ),
      });
  }

  /**
   * Settles the result list: assets never sent are marked skipped, and after an unexpected error the one in flight
   * failed. One asset that simply moved needs no report, so the dialog closes; otherwise the list stays up.
   */
  private finishBatch(error?: string): void {
    this.results.update((results) =>
      results.map((result) => {
        if (result.status === 'waiting') {
          return { ...result, status: 'skipped' };
        }
        if (result.status === 'moving' && isDefined(error)) {
          return { ...result, status: 'failed', message: error };
        }
        return result;
      }),
    );
    const results = this.results();
    if (
      isNullOrUndefined(error) &&
      results.length === 1 &&
      results[0].status === 'moved'
    ) {
      this.dialogRef.close();
      return;
    }
    this.finished.set(true);
  }

  /** Sends one move and reports how it went; errors become a result instead of failing the batch. */
  private moveOne(
    id: string,
    context: AssetMoveRequest,
  ): Observable<AssetMoveResult> {
    this.setResult({ id, name: this.nameOf(id), status: 'moving' });
    // Deferred, so an error thrown while building the request also becomes this asset's result.
    return defer(() =>
      this.entitiesService.moveAsset(id, context, 'body', false, {
        // The result list shows the reason, so the interceptor's toast is not needed.
        context: new HttpContext().set(SILENT_ERROR, true),
      }),
    ).pipe(
      map((response: AssetMoveResponse): AssetMoveResult => {
        // The original is now deleted in this client: close its details panel and refresh the list.
        this.broadcastService.broadcast('entity-deleted', {
          entityType: 'asset',
          operation: 'delete',
          entityId: id,
        });
        this.broadcastService.broadcast('entity-updated', {
          entityType: 'asset',
          operation: 'update',
          entityId: response.id,
        });
        return {
          id,
          name: this.nameOf(id),
          status:
            response.move?.outcome === AssetMoveSummary.OutcomeEnum.Restored
              ? 'restored'
              : 'moved',
        };
      }),
      catchError((error: unknown) => of(this.failureOf(id, error))),
    );
  }

  /**
   * 400, 404 and 409 mean the API refused the move and changed nothing (a duplicate, a deleted asset, another move
   * running). Anything else failed while moving; the API then says whether it undid the move.
   */
  private failureOf(id: string, error: unknown): AssetMoveResult {
    const apiError = error as Partial<ApiErrorResponse> | null;
    const status = apiError?.originalError?.status;
    const body = apiError?.originalError?.error as
      | { message?: unknown }
      | null
      | undefined;
    const serverMessage =
      typeof body?.message === 'string' && body.message !== ''
        ? body.message
        : undefined;
    // The interceptor already made a 400's validation text readable.
    const message =
      (status === 400 ? apiError?.errorMessage : serverMessage) ??
      apiError?.errorMessage ??
      this.translate.instant('ADMIN.ASSETS.MOVE.RESULT.UNKNOWN_ERROR');
    return {
      id,
      name: this.nameOf(id),
      status:
        status === 400 || status === 404 || status === 409
          ? 'blocked'
          : 'failed',
      message,
    };
  }

  private setResult(result: AssetMoveResult): void {
    this.results.update((results) =>
      results.map((current) => (current.id === result.id ? result : current)),
    );
  }

  private nameOf(id: string): string {
    const name = this.names.get(id);
    return isNullOrUndefined(name) || name === '' ? id : name;
  }

  protected statusIcon(status: AssetMoveStatus): string {
    switch (status) {
      case 'moving':
        return 'pi pi-spin pi-spinner text-surface-500';
      case 'moved':
        return 'pi pi-check-circle text-green-500';
      case 'restored':
        return 'pi pi-replay text-green-500';
      case 'blocked':
        return 'pi pi-ban text-orange-500';
      case 'failed':
        return 'pi pi-times-circle text-red-500';
      case 'skipped':
        return 'pi pi-minus-circle text-surface-400';
      default:
        return 'pi pi-clock text-surface-400';
    }
  }

  onClose(): void {
    this.dialogRef.close();
  }

  onCancel(): void {
    if (this.moving()) {
      // Aborting the request would not stop the move server-side, so let it finish and skip the rest.
      this.cancelRequested = true;
      return;
    }
    this.dialogRef.close();
  }

  private dropFromBulkSelection(movedIds: string[]): void {
    if (movedIds.length === 0) return;
    const moved = new Set(movedIds);
    this.bulkSelectionService.setAll(
      this.bulkSelectionService
        .checkedItems()
        .filter((item) => !moved.has(String(item.id))),
    );
  }
}
